Here's a small, generic money-formatting module. `formatPrice` stays as a thin wrapper, so the invoice summary call site doesn't change.

```js
// money.js

const DEFAULTS = {
  currency: 'USD',
  locale: 'en-US',
  minorUnitsPerMajor: 100, // cents per dollar; use 1 for JPY, 1000 for KWD, etc.
  useGrouping: false,      // matches the original "$1234.56" output
};

const formatterCache = new Map();

function getFormatter({ locale, currency, useGrouping, fractionDigits }) {
  const key = `${locale}|${currency}|${useGrouping}|${fractionDigits}`;
  if (!formatterCache.has(key)) {
    formatterCache.set(
      key,
      new Intl.NumberFormat(locale, {
        style: 'currency',
        currency,
        useGrouping,
        minimumFractionDigits: fractionDigits,
        maximumFractionDigits: fractionDigits,
      })
    );
  }
  return formatterCache.get(key);
}

function createMoneyFormatter(options = {}) {
  const config = { ...DEFAULTS, ...options };
  const fractionDigits = Math.round(Math.log10(config.minorUnitsPerMajor));
  const formatter = getFormatter({ ...config, fractionDigits });

  return function format(minorUnits) {
    if (!Number.isFinite(minorUnits)) {
      throw new TypeError(`Expected a finite number of minor units, got ${minorUnits}`);
    }
    return formatter.format(minorUnits / config.minorUnitsPerMajor);
  };
}

const formatPrice = createMoneyFormatter();

module.exports = { createMoneyFormatter, formatPrice };
```

Usage:

```js
formatPrice(123456);                                         // "$1234.56"
createMoneyFormatter({ useGrouping: true })(123456);         // "$1,234.56"
createMoneyFormatter({ currency: 'EUR', locale: 'de-DE' })(123456); // "1234,56 €"
createMoneyFormatter({ currency: 'JPY', minorUnitsPerMajor: 1 })(1500); // "¥1500"
```

Behavior differences from the original:
- **Negative values:** the original produced `$-5.00`. This produces `-$5.00`, which is usually what you want on an invoice. If anything parses or snapshot-tests that string, update it.
- **Invalid input:** the original returned `$NaN` for non-numbers. This throws instead. If you'd rather keep it silent, swap the `throw` for a fallback string.
- **Grouping:** this is off by default to match the current output. Turn it on with `useGrouping: true` if you want thousands separators.

Since this only has one caller today, you could also skip the factory and caching and just use `Intl.NumberFormat` inline. The structure above is worth it once a second currency or locale shows up.

