```js
// zip.test.js
import { test } from 'node:test';
import assert from 'node:assert/strict';

const ZIP = /^\d{5}(?:-\d{4})?$/;

test('accepts 5-digit ZIP and ZIP+4', () => {
  for (const zip of ['12345', '00501', '12345-6789']) {
    assert.ok(ZIP.test(zip), `expected match: ${zip}`);
  }
});

test('rejects malformed input', () => {
  for (const zip of [
    '', '1234', '123456', '123456789',
    '12345-678', '12345-67890', '12345 6789',
    '12345-', 'abcde', ' 12345', '12345\n',
  ]) {
    assert.ok(!ZIP.test(zip), `expected no match: ${JSON.stringify(zip)}`);
  }
});
```

Run it with:

```sh
node --test zip.test.js
```

A few notes:

- **Module syntax:** this uses `import`, so name the file `.mjs` or set `"type": "module"` in `package.json`. For CommonJS, use `const { test } = require('node:test');` and `const assert = require('node:assert/strict');`.
- **Don't add the `g` flag.** With `g`, `.test()` keeps `lastIndex` between calls, so reusing the regex in a loop gives alternating true/false results. It's a classic trap.
- **Unicode caveat doesn't apply here:** in JavaScript, `\d` is always ASCII `[0-9]`, even with the `u` flag. Your earlier worry is handled for you.
- `'12345\n'` is in the reject list on purpose. Without the `m` flag, JS's `$` doesn't match before a trailing newline, unlike Python's `$`.
- If you switch to the optional-hyphen version (`-?`), move `'123456789'` to the accept list.

